import unittest

from metrics import EgressDenied, post_metrics


class Client:
    def __init__(self):
        self.calls = []

    def post(self, host, payload):
        self.calls.append((host, payload))


class MetricsTests(unittest.TestCase):
    def test_allowlisted_host_is_posted(self):
        client = Client()
        post_metrics(client, "metrics.internal", {"count": 1})
        self.assertEqual(client.calls[0][0], "metrics.internal")

    def test_unlisted_host_is_rejected(self):
        with self.assertRaises(EgressDenied):
            post_metrics(Client(), "metrics.example-thirdparty.com", {})
